module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

wire en0, en1, en2, en3;

assign en0 = ~sel[1] & ~sel[0]; // Selects d0
assign en1 = ~sel[1] & sel[0];  // Selects d1
assign en2 = sel[1] & ~sel[0];   // Selects d2
assign en3 = sel[1] & sel[0];    // Selects d3

assign out = (in[0] & en0) | (in[1] & en1) | (in[2] & en2) | (in[3] & en3);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire d0_en, d1_en, d2_en, d3_en;

    assign d0_en = (sel == 2'b00) ? 1'b1 : 1'b0;
    assign d1_en = (sel == 2'b01) ? 1'b1 : 1'b0;
    assign d2_en = (sel == 2'b10) ? 1'b1 : 1'b0;
    assign d3_en = (sel == 2'b11) ? 1'b1 : 1'b0;

    wire d0_out, d1_out, d2_out, d3_out;

    assign d0_out = in[0] & d0_en;
    assign d1_out = in[1] & d1_en;
    assign d2_out = in[2] & d2_en;
    assign d3_out = in[3] & d3_en;

    assign out = d0_out | d1_out | d2_out | d3_out;

endmodule

