module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

    always @(*) begin
        case (in)
            4'b1000: code = 2'b00; // Highest priority
            4'b0100: code = 2'b01;
            4'b0010: code = 2'b10;
            4'b0001: code = 2'b11;
            default: code = 2'b00; // No active bit
        endcase
    end

endmodule

