module fsm_3state (
    input clk, reset,
    output reg [1:0] state
);

    parameter A = 2'b00, B = 2'b01, C = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= A;
        end else begin
            case (state)
                A: state <= B;
                B: state <= C;
                C: state <= A;
                default: state <= A; // Fallback to state A
            endcase
        end
    end

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State encoding
    parameter RED = 3'b001, YELLOW = 3'b010, GREEN = 3'b100;

    reg [2:0] state, next_state;

    // Timing parameters (for example purposes, can be adjusted)
    reg [31:0] counter;
    parameter RED_TIME = 32'd50_000_000;   // 50 million cycles
    parameter YELLOW_TIME = 32'd10_000_000; // 10 million cycles
    parameter GREEN_TIME = 32'd50_000_000;  // 50 million cycles

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= RED;
            counter <= 32'd0;
        end else begin
            state <= next_state;
            counter <= counter + 1;
        end
    end

    // Next state logic
    always @(*) begin
        case (state)
            RED: begin
                if (counter >= RED_TIME) begin
                    next_state = GREEN;
                    counter = 32'd0;
                end else begin
                    next_state = RED;
                end
            end
            GREEN: begin
                if (counter >= GREEN_TIME) begin
                    next_state = YELLOW;
                    counter = 32'd0;
                end else begin
                    next_state = GREEN;
                end
            end
            YELLOW: begin
                if (counter >= YELLOW_TIME) begin
                    next_state = RED;
                    counter = 32'd0;
                end else begin
                    next_state = YELLOW;
                end
            end
            default: next_state = RED; // Fallback state
        endcase
    end

    // Output logic
    assign light = state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State encoding
    parameter RED = 3'b001;
    parameter YELLOW = 3'b010;
    parameter GREEN = 3'b100;

    reg [2:0] current_state, next_state;

    // State transition logic
    always @(*) begin
        case (current_state)
            RED: next_state = GREEN; // Transition from RED to GREEN
            GREEN: next_state = YELLOW; // Transition from GREEN to YELLOW
            YELLOW: next_state = RED; // Transition from YELLOW to RED
            default: next_state = RED; // Default state
        endcase
    end

    // State register with reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= RED; // Initialize to RED state
        end else begin
            current_state <= next_state; // Update state
        end
    end

    // Output logic
    assign light = current_state;

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    reg [1:0] state, next_state;
    parameter RED = 2'b00, YELLOW = 2'b01, GREEN = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= RED;
        else
            state <= next_state;
    end

    always @(*) begin
        case (state)
            RED: next_state = GREEN;
            GREEN: next_state = YELLOW;
            YELLOW: next_state = RED;
            default: next_state = RED;
        endcase
    end

    assign light = (state == RED) ? 3'b100 :
                   (state == YELLOW) ? 3'b010 :
                   (state == GREEN) ? 3'b001 : 3'b000;

endmodule

