module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // State encoding
    parameter RED = 3'b001, YELLOW = 3'b010, GREEN = 3'b100;

    reg [2:0] current_state, next_state;

    // Timing parameters
    reg [3:0] counter;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= RED; // Initialize to RED state
            counter <= 0;
        end else begin
            current_state <= next_state;
            counter <= counter + 1;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            RED: begin
                if (counter == 4'd9) // Stay RED for a certain time
                    next_state = GREEN;
                else
                    next_state = RED;
            end
            GREEN: begin
                if (counter == 4'd6) // Stay GREEN for a certain time
                    next_state = YELLOW;
                else
                    next_state = GREEN;
            end
            YELLOW: begin
                if (counter == 4'd3) // Stay YELLOW for a certain time
                    next_state = RED;
                else
                    next_state = YELLOW;
            end
            default: next_state = RED; // Default to RED
        endcase
    end

    // Output logic
    assign light = current_state;

endmodule

