assign p1 = a & {4{b[1]}};
assign p2 = a & {4{b[2]}};
assign p3 = a & {4{b[3]}};

// Shift partial products
assign sum1 = {4'b0, p0} + {3'b0, p1, 1'b0} + {2'b0, p2, 2'b00} + {1'b0, p3, 3'b000};

// Final output
assign out = sum1;

endmodule

