    input [7:0] x0,x1,x2,x3,
    output reg [7:0] max_value
);

reg [7:0] stage1_max1, stage1_max2;
reg [7:0] pipeline_max;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        stage1_max1 <= 8'b0;
        stage1_max2 <= 8'b0;
        pipeline_max <= 8'b0;
        max_value <= 8'b0;
    end else begin
        // Stage 1: Compare pairs
        stage1_max1 <= (x0 > x1) ? x0 : x1;
        stage1_max2 <= (x2 > x3) ? x2 : x3;
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        pipeline_max <= 8'b0;
        max_value <= 8'b0;
    end else begin
        // Stage 2: Final comparison
        pipeline_max <= (stage1_max1 > stage1_max2) ? stage1_max1 : stage1_max2;
        max_value <= pipeline_max;
    end
end

endmodule

