    reg [15:0] prod [0:3]; // Products of input and coefficients
    reg [15:0] sum_stage1; // Sum after stage 1
    reg [15:0] sum_stage2; // Sum after stage 2

    // Coefficients initialization (example values)
    initial begin
        coeff[0] = 8'd1;
        coeff[1] = 8'd2;
        coeff[2] = 8'd3;
        coeff[3] = 8'd4;
