module polynomial_1 (
    input signed [7:0] in_0,
    output signed [15:0] out
);

wire signed [15:0] x_squared;
wire signed [15:0] two_x;
wire signed [15:0] intermediate_sum;

assign x_squared = in_0 * in_0;       // Calculate x^2
assign two_x = in_0 << 1;             // Calculate 2x
assign intermediate_sum = x_squared + two_x + 1; // Sum x^2 + 2x + 1
assign out = intermediate_sum;         // Assign final output

endmodule

