module compound_interest (
    input [15:0] P,
    input [7:0] r,
    input [7:0] n,
    output reg [31:0] A
);

    reg [23:0] base; // 1 + r in fixed-point representation
    reg [31:0] power; // (1 + r)^n
    reg [31:0] temp; // Temporary variable for multiplication
    integer i;

    always @(*) begin
        // Calculate (1 + r) in fixed-point
        base = {8'b0, r} + 24'h100000; // 1 in fixed-point (1.0)

        // Initialize power to 1
        power = 32'h1;

        // Compute (1 + r)^n
        temp = base;
        for (i = 0; i < n; i = i + 1) begin
            power = power * temp;
        end

        // Calculate final amount A = P * (1 + r)^n
        A = P * power;
    end

endmodule

