    reg [31:0] power; // (1 + r)^n
    reg [7:0] i; // loop counter

    always @(*) begin
        // Calculate (1 + r) in fixed-point format
        base = {16'b0, r} + 24'h100000; // Adding 1 (in fixed-point)

        // Initialize power to 1
        power = 32'h1;

        // Exponentiation by repeated multiplication
        for (i = 0; i < n; i = i + 1) begin
            power = (power * base) >> 24; // Adjusting for the fixed-point scaling
        end

        // Final calculation of A = P * (1 + r)^n
        A = P * power;
    end

endmodule

